import * as THREE from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  // ----- Helpers -----
  const getVec3 = (src, defaults) => new THREE.Vector3(
    src?.x ?? defaults.x,
    src?.y ?? defaults.y,
    src?.z ?? defaults.z
  );

  // ----- Geometry & Material -----
  const sourceRect = config.atlasRegion?.sourceRect ?? { width: 512, height: 320 };
  const aspect = sourceRect.height / sourceRect.width;
  const geometry = new THREE.PlaneGeometry(1, aspect);

  const textureUrl = config.imageUrl ?? config.assets?.imageUrl;
  const texture = ctx.textureLoader(textureUrl);
  const material = new MeshBasicNodeMaterial({ map: texture });
  const mesh = new THREE.Mesh(geometry, material);
  mesh.position.set(0, 0, 0);
  mesh.scale.set(1, 1, 1);

  // ----- Container Object -----
  const node = new THREE.Object3D();
  node.add(mesh);

  // Apply placement
  node.position.copy(getVec3(config.position, { x: 0, y: 0, z: 0 }));
  node.rotation.copy(getVec3(config.rotation, { x: 0, y: 0, z: 0 }));
  node.scale.copy(getVec3(config.scale, { x: 1, y: 1, z: 1 }));

  // ----- Cinematic Primitives -----
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const apply = ctx.primitives[prim.name];
      if (typeof apply === 'function') {
        apply(node, prim.params ?? {});
      }
    }
  }

  // ----- Interaction Handlers -----
  const handlers = {};

  let hoverTween = null;
  let outTween = null;
  let clickTimeline = null;

  handlers.hover = () => {
    if (outTween) { outTween.kill(); outTween = null; }
    hoverTween = gsap.to(node.position, {
      y: node.position.y + 0.15,
      duration: 0.7,
      ease: 'power3.out'
    });
  };

  handlers.unhover = () => {
    if (hoverTween) { hoverTween.kill(); hoverTween = null; }
    outTween = gsap.to(node.position, {
      y: node.position.y - 0.15,
      duration: 0.7,
      ease: 'power3.out'
    });
  };

  handlers.click = () => {
    if (clickTimeline) { clickTimeline.kill(); }
    clickTimeline = gsap.timeline()
      .to(node.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'back.out(1.7)'
      })
      .to(node.scale, {
        x: 1,
        y: 1,
        z: 1,
        duration: 0.12,
        ease: 'back.out(1.7)'
      });
    if (typeof ctx.emit === 'function') {
      ctx.emit('hub-journal.select');
    }
  };

  // Assign handlers to userData
  node.userData.handlers = handlers;

  // ----- Cleanup -----
  node.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (texture && texture.dispose) texture.dispose();

    if (hoverTween) hoverTween.kill();
    if (outTween) outTween.kill();
    if (clickTimeline) clickTimeline.kill();

    // Dispose children recursively
    node.traverse((obj) => {
      if (obj.geometry) obj.geometry.dispose();
      if (obj.material) {
        if (Array.isArray(obj.material)) {
          obj.material.forEach((m) => m.dispose && m.dispose());
        } else {
          obj.material.dispose();
        }
      }
    });
  };

  return node;
}
